-- TABELA: public."audit_logs"
CREATE TABLE IF NOT EXISTS public."audit_logs" ("id" uuid DEFAULT gen_random_uuid(), "user_id" uuid, "action" text, "entity" text, "entity_id" text, "old_data" jsonb, "new_data" jsonb, "created_at" timestamptz DEFAULT now(), PRIMARY KEY ("id"));
ALTER TABLE public."audit_logs" ENABLE ROW LEVEL SECURITY;
DO $$ BEGIN CREATE POLICY "allow_all_audit_logs" ON public."audit_logs" FOR ALL USING (true) WITH CHECK (true); EXCEPTION WHEN duplicate_object THEN null; END $$;
GRANT ALL ON TABLE public."audit_logs" TO anon, authenticated, service_role;

